use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's HTTPClient handle is scoped to. The host enforces the
/// allowlist by trapping. We check it here first, so that one stray
/// subscription becomes a recorded failure and does not abort the whole run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Extract the lowercase host from an http(s) URL, or explain why it has none.
fn host_of(url: &str) -> Result<String, String> {
    let trimmed = url.trim();
    let lower = trimmed.to_ascii_lowercase();
    let rest = if lower.starts_with("https://") {
        &trimmed["https://".len()..]
    } else if lower.starts_with("http://") {
        &trimmed["http://".len()..]
    } else {
        return Err("unsupported URL scheme (expected http or https)".to_string());
    };

    // Authority ends at the first '/', '?' or '#'.
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    // Drop any userinfo.
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };

    // Drop the port (no IPv6 literals are on the allowlist; reject them).
    if host_port.starts_with('[') {
        return Err("IP-literal hosts are not permitted".to_string());
    }
    let host = match host_port.find(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };
    let host = host.trim_end_matches('.').to_ascii_lowercase();

    if host.is_empty() {
        return Err("URL has no host".to_string());
    }
    Ok(host)
}

fn permitted(url: &str) -> Result<(), String> {
    let host = host_of(url)?;
    if ALLOWED_HOSTS.iter().any(|h| *h == host) {
        Ok(())
    } else {
        Err(format!("host '{}' is not in this node's allowlist", host))
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            let url = url.trim().to_string();
            if url.is_empty() {
                continue;
            }

            if let Err(error) = permitted(&url) {
                failures.push(FetchFailure { url, error });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
